// Release signing for Google Play. `android/` is generated by prebuild, so the
// signing config is injected here rather than edited by hand.
//
// The upload keystore and its passwords live in credentials/ at the project
// root, which is git-ignored:
//   credentials/upload-keystore.jks
//   credentials/upload.properties   (storePassword, keyAlias, keyPassword)
// Without that file the release build falls back to the debug key, so a
// fresh checkout still builds -- but only a build signed with the upload key
// can be uploaded to Play.
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// withReleaseSigning';

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    let src = cfg.modResults.contents;
    if (src.includes(MARKER)) return cfg;

    src = src.replace(
      /signingConfigs \{\n/,
      `signingConfigs {
        ${MARKER}
        def uploadProps = new Properties()
        def uploadFile = rootProject.file('../credentials/upload.properties')
        if (uploadFile.exists()) {
            uploadFile.withInputStream { uploadProps.load(it) }
            release {
                storeFile rootProject.file('../credentials/upload-keystore.jks')
                storePassword uploadProps['storePassword']
                keyAlias uploadProps['keyAlias']
                keyPassword uploadProps['keyPassword']
            }
        }
`,
    );
    // The template signs release builds with the debug key; use the upload key
    // when it is configured.
    src = src.replace(
      /(release \{\n(?:(?!\n {8}\}).)*?)signingConfig signingConfigs\.debug/s,
      '$1signingConfig signingConfigs.findByName(\'release\') ?: signingConfigs.debug',
    );
    cfg.modResults.contents = src;
    return cfg;
  });
};
